const crypto = require('crypto');

// Obtém credenciais das variáveis de ambiente ou configurações do n8n
const appId = $env.SHOPEE_APP_ID || 'SEU_SHOPEE_APP_ID';
const secret = $env.SHOPEE_SECRET || 'SEU_SHOPEE_SECRET';

const items = $input.all();
const requests = [];

for (const item of items) {
  const categoria = item.json.categoria || 'Geral';
  const timestamp = Math.floor(Date.now() / 1000);

  // Query GraphQL oficial da Shopee Affiliate Open API
  const graphQlQuery = `
    query GetOffers($keyword: String, $page: Int, $limit: Int, $sortType: Int) {
      productOfferV2(keyword: $keyword, page: $page, limit: $limit, sortType: $sortType) {
        nodes {
          itemId
          productName
          imageUrl
          priceMin
          priceMax
          priceDiscountRate
          sales
          ratingStar
          shopName
          productLink
          offerLink
        }
      }
    }
  `;

  const payloadObj = {
    query: graphQlQuery,
    variables: {
      keyword: categoria,
      page: 1,
      limit: 25,
      sortType: 1 // Ordenar por mais vendidos/destaques
    }
  };

  const payloadStr = JSON.stringify(payloadObj);

  // Cálculo da assinatura oficial Shopee SHA256
  const factor = appId + timestamp + payloadStr + secret;
  const signature = crypto.createHash('sha256').update(factor).digest('hex');

  requests.push({
    json: {
      categoria: categoria,
      payload: payloadObj,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `SHA256 Credential=${appId}, Timestamp=${timestamp}, Signature=${signature}`
      }
    }
  });
}

return requests;

const items = $input.all();
const produtosMapeados = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  // Categoria consultada nessa iteração correspondente
  const categoria = $('Preparar Requisicao Shopee API').all()[i]?.json?.categoria || 'Geral';

  const nodes = res?.data?.productOfferV2?.nodes || [];

  for (const prod of nodes) {
    if (!prod.itemId || !prod.productName) continue;

    const preco = parseFloat(prod.priceMin || prod.priceMax || 0);
    const descontoRate = parseFloat(prod.priceDiscountRate || 0);

    // Calcula preco antigo estimado se houver desconto
    let precoAntigo = preco;
    if (descontoRate > 0) {
      precoAntigo = parseFloat((preco / (1 - (descontoRate / 100))).toFixed(2));
    }

    produtosMapeados.push({
      json: {
        shopee_item_id: String(prod.itemId),
        nome: prod.productName,
        imagem: prod.imageUrl || '',
        preco: preco,
        preco_antigo: precoAntigo,
        desconto: descontoRate,
        avaliacao: parseFloat(prod.ratingStar || 0),
        vendas: parseInt(prod.sales || 0, 10),
        categoria: categoria,
        loja: prod.shopName || 'Loja Shopee',
        url_original: prod.productLink || '',
        url_afiliado: prod.offerLink || prod.productLink || '',
        status: 'encontrado',
        marketplace: 'shopee'
      }
    });
  }
}

return produtosMapeados;

